      "keystrokes": "cat > fill_offer_letter.py << 'EOF'
import json
from docx import Document
import re

# Load employee data
with open('employee_data.json', 'r') as f:
    data = json.load(f)

# Open the template
doc = Document('offer_letter_template.docx')

def replace_placeholders(text, data):
    """Replace all {{PLACEHOLDER}} with actual values"""
    if not text:
        return text

    for key, value in data.items():
        placeholder = '{{' + key + '}}'
        text = text.replace(placeholder, str(value))

    return text

def process_conditional(text, data):
    """Handle IF_RELOCATION conditional sections"""
    if not text:
        return text

    # Check if relocation package is Yes
    if data.get('RELOCATION_PACKAGE', '').lower() == 'yes':
        # Keep content but remove the IF/END_IF markers
        text = re.sub(r'\{\{IF_RELOCATION\}\}', '', text)
        text = re.sub(r'\{\{END_IF_RELOCATION\}\}', '', text)
    else:
        # Remove entire conditional section including content
        text = re.sub(r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}', '', text, flags=re.DOTALL)

    return text

# Process paragraphs
for paragraph in doc.paragraphs:
    if paragraph.text:
        # First handle conditionals
        new_text = process_conditional(paragraph.text, data)
        # Then replace placeholders
        new_text = replace_placeholders(new_text, data)

        # Update paragraph text while preserving formatting
        if new_text != paragraph.text:
            # Clear existing runs and add new text
            for run in paragraph.runs:
                run.text = ''
            if paragraph.runs:
                paragraph.runs[0].text = new_text
            else:
                paragraph.add_run(new_text)

# Process tables
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for paragraph in cell.paragraphs:
                if paragraph.text:
                    new_text = process_conditional(paragraph.text, data)
                    new_text = replace_placeholders(new_text, data)

                    if new_text != paragraph.text:
                        for run in paragraph.runs:
                            run.text = ''
                        if paragraph.runs:
                            paragraph.runs[0].text = new_text
                        else:
                            paragraph.add_run(new_text)

# Save the filled document
doc.save('/root/offer_letter_filled.docx')
print('Offer letter successfully created at /root/offer_letter_filled.docx')
EOF
